() => {
 if (window.__api6Observer) return {alreadyInstalled:true,timeOrigin:performance.timeOrigin};
 const events=[]; const record=x=>{if(events.length<6000)events.push({at:Date.now(),...x});};
 const fetchOriginal=window.fetch;
 window.fetch=async function(...args) {
  const url=String(args[0]?.url||args[0]); const body=args[1]?.body;
  record({kind:'http_request',url,body:typeof body==='string'?body:null});
  const response=await fetchOriginal.apply(this,args);
  response.clone().text().then(body=>record({kind:'http_response',url,status:response.status,body})).catch(e=>record({kind:'http_capture_error',message:String(e)}));
  return response;
 };
 const OriginalSocket=window.WebSocket;
 window.WebSocket=class extends OriginalSocket {
   constructor(...args){super(...args);const url=String(args[0]);record({kind:'ws_construct',url});
    this.addEventListener('open',()=>record({kind:'ws_open',url}));
    this.addEventListener('message',event=>record({kind:'ws_message',url,data:event.data}));
    this.addEventListener('close',event=>record({kind:'ws_close',url,code:event.code}));
   }
   send(data){record({kind:'ws_send',url:this.url,data});return super.send(data);}
 };
 window.__api6Observer={events,marker:crypto.randomUUID(),timeOrigin:performance.timeOrigin};
 return {installed:true,marker:window.__api6Observer.marker,timeOrigin:performance.timeOrigin,href:location.href};
}
